#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdint>

using namespace std;

class Main {
private:
    static int weight;
    static int itemMass;
    static vector<bool> arr;
public:
    bool isBalanced() {
        bool isBalance = false;
        int64_t pod1 = itemMass, pod2 = 0;
        while (true) {
            if (pod1 > pod2) {
                int64_t nextMass = getMass(pod1 - pod2);
                if (nextMass != 0) {
                    pod2 += nextMass;
                } else {
                    break;
                }
            } else if (pod1 < pod2) {
                int64_t nextMass1 = getMass(pod2 - pod1);
                if (nextMass1 != 0) {
                    pod1 += nextMass1;
                } else {
                    break;
                }
            } else {
                isBalance = true;
                break;
            }
        }
        return isBalance;
    }

    int64_t getMass(int64_t mass) {
        int64_t result = 0;
        int logBase = (int)(log((double)mass) / log((double)weight));
        // Ensure logBase is at least 0
        if (logBase < 0) logBase = 0;
        // To prevent negative index
        int index = logBase;
        int nextIndex = logBase + 1;

        // Calculate sumTotal
        // sumTotal = (weight^{logBase+1} - 1) / (weight - 1)
        // Use 64-bit integer arithmetic
        __int128 bi = 1;
        for (int i = 0; i <= logBase; ++i) {
            bi *= weight;
        }
        __int128 sumTotal = (bi - 1) / (weight - 1);

        if (mass > (int64_t)sumTotal && !arr[nextIndex]) {
            // result = weight^{logBase+1}
            int64_t powResult = 1;
            for (int i = 0; i <= logBase; ++i) {
                powResult *= weight;
            }
            result = powResult;
            arr[nextIndex] = true;
        } else if (mass <= (int64_t)sumTotal && !arr[index]) {
            // result = weight^{logBase}
            int64_t powResult = 1;
            for (int i = 0; i < logBase; ++i) {
                powResult *= weight;
            }
            result = powResult;
            arr[index] = true;
        } else {
            result = 0;
        }
        return result;
    }
};

int Main::weight = 0;
int Main::itemMass = 0;
vector<bool> Main::arr(100, false);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> Main::weight >> Main::itemMass;
    Main wb;
    if (wb.isBalanced())
        cout << "YES\n";
    else
        cout << "NO\n";
    return 0;
}

